import os
import json
import shutil
import numpy as np
import pyarrow as pa
import lancedb

DB_URI = "/home/user/db"
TABLE_NAME = "articles"
OUT_PATH = "/home/user/output/fts_results.json"

# Clean start
if os.path.isdir(DB_URI):
    shutil.rmtree(DB_URI)

# Schema with fixed_size_list<float32>[4] represented as pa.list_(pa.float32(), 4)
schema = pa.schema([
    pa.field("id", pa.int64()),
    pa.field("title", pa.string()),
    pa.field("body", pa.string()),
    pa.field("vector", pa.list_(pa.float32(), 4)),
])

rng = np.random.default_rng(1)

# Build rows. id=1 must be top hit for 'vector database'; id=2 for 'lance format'.
rows = [
    {
        "id": 1,
        "title": "Vector Databases Explained",
        "body": "A vector database stores high dimensional embeddings and supports nearest neighbor search at scale. Vector database systems power semantic retrieval, recommendation engines, and similarity search across millions of items. Choosing the right vector database involves tradeoffs in latency, recall, and storage.",
    },
    {
        "id": 2,
        "title": "The Lance Format for Columnar Data",
        "body": "The lance format is a modern columnar storage format designed for machine learning workloads. The lance format combines random access, version control, and efficient scans in a single file. With the lance format you can append, update, and slice data without rewriting the whole dataset.",
    },
    {
        "id": 3,
        "title": "Introduction to BM25",
        "body": "BM25 is a ranking function used by search engines to estimate the relevance of documents to a query. BM25 scores documents based on term frequency, inverse document frequency, and document length normalization. It remains a strong baseline for information retrieval tasks.",
    },
    {
        "id": 4,
        "title": "Embeddings 101",
        "body": "Word and sentence embeddings map text into dense numeric vectors that capture semantic meaning. Modern transformer models produce high quality embeddings suitable for clustering and similarity tasks.",
    },
    {
        "id": 5,
        "title": "Approximate Nearest Neighbors",
        "body": "ANN algorithms such as HNSW and IVF trade a small amount of recall for dramatic speedups over brute force nearest neighbor search. They are the workhorses behind large scale retrieval systems.",
    },
    {
        "id": 6,
        "title": "Information Retrieval Basics",
        "body": "Information retrieval is the science of searching for information within documents, metadata, and databases. Classic IR systems rely on inverted indexes and term weighting schemes like TF-IDF and BM25.",
    },
    {
        "id": 7,
        "title": "Tokenization in Search",
        "body": "Tokenization splits text into tokens such as words, subwords, or n-grams. Good tokenization dramatically improves recall and precision in full text search systems.",
    },
    {
        "id": 8,
        "title": "Inverted Indexes",
        "body": "An inverted index maps each term to the list of documents that contain it. Search engines use inverted indexes for fast keyword lookup and ranking.",
    },
    {
        "id": 9,
        "title": "Hybrid Search Strategies",
        "body": "Hybrid search combines keyword matching with vector similarity to leverage the strengths of both approaches. Lexical search is precise for rare terms while vector search captures semantic intent.",
    },
    {
        "id": 10,
        "title": "Columnar Storage Overview",
        "body": "Columnar storage formats like Parquet and ORC store data by column rather than by row. This layout improves compression and analytical query performance.",
    },
    {
        "id": 11,
        "title": "Row vs Columnar",
        "body": "Row based layouts favor write heavy transactional workloads while columnar formats excel at read heavy analytical workloads. Choosing the right layout depends on access patterns.",
    },
    {
        "id": 12,
        "title": "Search Ranking Signals",
        "body": "Search engines combine many signals such as term frequency, document freshness, and link popularity to produce a final ranking. BM25 provides a solid lexical baseline.",
    },
    {
        "id": 13,
        "title": "Cosine Similarity",
        "body": "Cosine similarity measures the angle between two vectors and is widely used for comparing embeddings. It is robust to vector magnitude differences.",
    },
    {
        "id": 14,
        "title": "Sparse vs Dense Retrieval",
        "body": "Sparse retrieval uses inverted indexes over bag of words representations while dense retrieval relies on neural encoders. Both families of methods have complementary strengths.",
    },
    {
        "id": 15,
        "title": "TF-IDF Fundamentals",
        "body": "TF-IDF weights terms by how often they appear in a document relative to the entire corpus. It is a precursor to modern ranking functions like BM25.",
    },
    {
        "id": 16,
        "title": "Stopword Filtering",
        "body": "Stopwords such as the, is, and at are usually filtered out during indexing because they carry little discriminative signal.",
    },
    {
        "id": 17,
        "title": "Stemming and Lemmatization",
        "body": "Stemming reduces words to their root form to improve recall. Lemmatization goes a step further using vocabulary and morphological analysis.",
    },
    {
        "id": 18,
        "title": "Data Versioning",
        "body": "Data versioning allows teams to track changes to datasets over time. Versioned datasets enable reproducibility and auditability in machine learning pipelines.",
    },
    {
        "id": 19,
        "title": "Apache Arrow Basics",
        "body": "Apache Arrow defines a cross language columnar memory format. It enables zero copy data exchange between analytics engines.",
    },
    {
        "id": 20,
        "title": "LanceDB Internals",
        "body": "LanceDB is an open source database for AI applications built on the Lance columnar format. It combines vector search, full text search, and SQL style filtering in a single engine.",
    },
    {
        "id": 21,
        "title": "Reranking with Cross Encoders",
        "body": "Cross encoders rerank candidate passages using a deep transformer that jointly encodes the query and document. They are slower but more accurate than bi-encoders.",
    },
]

